const app=document.querySelector('#desk-app');
if(new URLSearchParams(location.search).has('stage'))document.body.classList.add('stage-mode');
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',arrivals:'<path d="M3 21h18M5 21V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v16M9 7h.01M15 7h.01M9 11h.01M15 11h.01M10 21v-5h4v5"/>',rooms:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 11h18M8 11v9M16 11v9"/>',service:'<path d="M5 8h14M5 12h14M5 16h9M3 4h18v16H3z"/>'};
const ico=name=>`<svg aria-hidden="true" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${icons[name]}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=()=>({
  guests:[
    {id:'HBL-48026',name:'Maya Chen',initials:'MC',type:'King',nights:2,party:2,status:'Arriving',time:'15:00',note:'Late arrival noted',room:null},
    {id:'HBL-48031',name:'Daniel Brooks',initials:'DB',type:'King',nights:1,party:1,status:'Arriving',time:'16:30',note:'Requested a quiet room',room:null},
    {id:'HBL-48039',name:'Priya Shah',initials:'PS',type:'Two queens',nights:3,party:3,status:'Arriving',time:'18:00',note:'Adjoining room requested',room:null},
    {id:'HBL-47980',name:'Ava Morgan',initials:'AM',type:'King',nights:2,party:2,status:'In house',time:'Yesterday',note:'',room:'409'},
    {id:'HBL-47988',name:'Oliver Grant',initials:'OG',type:'King',nights:2,party:1,status:'In house',time:'Yesterday',note:'',room:'612'}
  ],
  rooms:[
    {number:'608',type:'King',status:'Ready',floor:'6th floor'},
    {number:'714',type:'King',status:'Ready',floor:'7th floor'},
    {number:'314',type:'Two queens',status:'Cleaning',floor:'3rd floor'},
    {number:'409',type:'King',status:'Occupied',floor:'4th floor'},
    {number:'612',type:'King',status:'Occupied',floor:'6th floor'},
    {number:'420',type:'Two queens',status:'Cleaning',floor:'4th floor'}
  ],
  tasks:[{id:1,room:'314',category:'Housekeeping',note:'Final room inspection before arrival',status:'Open',owner:'Rooms team'}],
  activity:[{title:'Night shift opened',detail:'Sample property state loaded · all data is local to this page'}]
});
const entraIdentity=window.__deskIdentity||null;
const persona=new URLSearchParams(location.search).get('persona');
const propertyDemo=persona==='jordan'||persona==='samfed';
const properties={franchise:{name:'Bayside House',place:'Bayside · franchise'},managed:{name:'Harbor View',place:'Seattle · managed hotel'}};
let phase='franchise',selectedProperty='franchise';
let data=seed(),view='overview',drawer=null,search='',operator=entraIdentity?.name||(persona==='jordan'?'Jordan Vale':persona==='sofia'?'Sofia Alvarez':new URLSearchParams(location.search).get('workspace')==='contactcenter'?'Nadia Haddad':'Sam Okoro'),locked=false,toastTimer;
const allowedProperty=()=>persona==='samfed'?'franchise':phase==='managed'?'managed':'franchise';
const propertyAllowed=()=>!propertyDemo||selectedProperty===allowedProperty();
// The workspace is decided by the app role in the token (use case 33): Desk.ContactCenter, Desk.Housekeeping or Desk.FrontOffice.
// ?workspace=contactcenter previews the contact-centre desk without a sign-in.
const roles=(entraIdentity&&entraIdentity.roles)||[];
const wsParam=new URLSearchParams(location.search).get('workspace');
const workspace=wsParam||(roles.includes('Desk.ContactCenter')?'contactcenter':roles.includes('Desk.Housekeeping')?'housekeeping':'frontdesk');
const roleLabel=roles.length?roles.join(', '):(workspace==='contactcenter'?'Desk.ContactCenter · preview':workspace==='housekeeping'?'Desk.Housekeeping · preview':'Desk.FrontOffice · preview');
const wsTitle={contactcenter:'CONTACT CENTER',housekeeping:'HOUSEKEEPING',frontdesk:'FRONT DESK'}[workspace];
const ccSeed=()=>({
  queue:[
    {id:'C-1041',caller:'Helen Ward',hotel:'Elliott Landing, Seattle',reason:'Move arrival to Friday',wait:'0:42',status:'Waiting'},
    {id:'C-1042',caller:'Marcus Lee',hotel:'Cannery Pier, Portland',reason:'Add a second room',wait:'1:15',status:'Waiting'},
    {id:'C-1043',caller:'Sofia Ruiz',hotel:'Biscayne Slip, Miami',reason:'Confirm airport shuttle',wait:'2:03',status:'Waiting'},
    {id:'C-1039',caller:'Grace Park',hotel:'Long Wharf Commons, Boston',reason:'Invoice copy',wait:'On call',status:'On call'}],
  reservations:[
    {id:'HBL-51022',name:'Helen Ward',hotel:'Elliott Landing, Seattle',dates:'Oct 3 to 5',type:'King',status:'Confirmed'},
    {id:'HBL-51031',name:'Marcus Lee',hotel:'Cannery Pier, Portland',dates:'Oct 9 to 12',type:'Two queens',status:'Confirmed'},
    {id:'HBL-51044',name:'Sofia Ruiz',hotel:'Biscayne Slip, Miami',dates:'Oct 14 to 18',type:'Suite',status:'Confirmed'},
    {id:'HBL-50990',name:'Grace Park',hotel:'Long Wharf Commons, Boston',dates:'Sep 18 to 20',type:'King',status:'Departed'},
    {id:'HBL-51050',name:'Daniel Brooks',hotel:'Ballard Locks House, Seattle',dates:'Oct 2 to 3',type:'King',status:'Hold'}],
  callbacks:[{id:1,name:'Ava Morgan',hotel:'Embarcadero Quay, San Francisco',note:'Call back about late checkout on Oct 6',status:'Open'},{id:2,name:'Oliver Grant',hotel:'Elliott Landing, Seattle',note:'Send folio copy for expenses',status:'Open'}],
  activity:[{title:'Remote shift opened',detail:'Working from home over the internet · all data is local to this page'}]
});
let cc=ccSeed(),ccView='overview',ccSearch='';
function ccRecord(title,detail){cc.activity.unshift({title,detail:`${now()} · ${detail}`});cc.activity=cc.activity.slice(0,8)}
function ccHeader(){return `<aside class="rail"><div class="rail-brand"><img src="./assets/harborline-mark.svg" alt=""><div><strong>Harborline</strong><small>${wsTitle}</small></div></div><div><span class="rail-group-label">WORKSPACE</span><nav class="rail-nav" aria-label="Contact center navigation">${[['overview','Overview','overview'],['queue','Call queue','service'],['reservations','Reservations','arrivals'],['callbacks','Callbacks','rooms']].map(([key,label,icon])=>`<button type="button" data-ccview="${key}" aria-label="${label}" ${ccView===key?'aria-current="page"':''}>${ico(icon)}<span>${label}</span></button>`).join('')}</nav></div><div class="rail-bottom"><strong>Harborline Contact Center</strong>Remote · all hotels<br>Role in token: ${esc(roleLabel)}</div></aside><div class="desk-main"><header class="topline"><div class="property"><i class="property-mark" aria-hidden="true"></i><strong>Contact Center</strong><span>· every Harborline hotel</span></div><div class="top-actions"><span class="demo-pill">DEMO DATA · NOT CONNECTED TO CRS</span>${entraIdentity?'<span class="identity-pill">ENTRA SESSION</span><button class="top-signout" type="button" data-action="sign-out">Sign out</button>':'<a class="top-signin" href="https://kind-beach-0ba2dc30f.6.azurestaticapps.net/desk-auth.html?tenant=workforce" target="_blank" rel="noopener noreferrer">Sign in with Entra ↗</a>'}<div class="operator">${operatorImage()}<span><strong>${esc(operator)}</strong><small>${entraIdentity?esc(entraIdentity.username):'Remote agent'}</small></span></div></div></header><main class="main-inner" id="desk-main">`}
function ccLead(kicker,title,description,action=''){return `<div class="page-lead"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="lead-actions">${action}</div></div>`}
function ccRoleNote(){return `<section class="panel"><div class="panel-head"><div><h2>Why this desk</h2><p>Authentication proved who signed in; the role in the token chose the workspace</p></div></div><div class="side-panel-body"><p class="muted">${esc(operator)} carries <strong>${esc(roleLabel)}</strong>. A front-office role would open the property desk with rooms and keys; this role opens reservations and the call queue across every hotel, with no room or key controls. Same application, different authorisation.</p></div></section>`}
function ccActivity(){return `<section class="panel"><div class="panel-head"><div><h2>Shift activity</h2><p>Actions in this demo session</p></div></div><div class="side-panel-body activity">${cc.activity.map(a=>`<div class="activity-item"><i aria-hidden="true"></i><div><strong>${esc(a.title)}</strong><small>${esc(a.detail)}</small></div></div>`).join('')}</div></section>`}
function callRow(c){return `<div class="row static"><span class="row-icon">${esc(c.caller.split(' ').map(x=>x[0]).join(''))}</span><span class="row-main"><strong>${esc(c.caller)}</strong><small>${esc(c.hotel)} · ${esc(c.reason)}</small></span><span class="row-end"><span class="status ${mark(c.status)}">${esc(c.status)}</span><small>${esc(c.wait)}</small></span>${c.status==='Waiting'?`<button class="btn subtle" type="button" data-take="${esc(c.id)}">Take call</button>`:c.status==='On call'?`<button class="btn subtle" type="button" data-wrap="${esc(c.id)}">Wrap up</button>`:''}</div>`}
function ccOverview(){const waiting=cc.queue.filter(c=>c.status==='Waiting').length;return `${ccLead('Remote shift','Good morning, '+operator.split(' ')[0]+'.','Work the queue, find any reservation at any hotel, and clear callbacks before the shift ends.',`<button class="btn primary" type="button" data-ccview="queue">Open the queue →</button>`)}<div class="stats">${stat('Calls waiting',waiting,'Across all hotels',waiting>2)}${stat('On call',cc.queue.filter(c=>c.status==='On call').length,'Right now')}${stat('Reservations',cc.reservations.filter(r=>r.status!=='Departed').length,'Active in this demo')}${stat('Callbacks open',cc.callbacks.filter(t=>t.status==='Open').length,'Promised today',cc.callbacks.some(t=>t.status==='Open'))}</div><div class="split"><section class="panel"><div class="panel-head"><div><h2>Next in queue</h2><p>Longest waiting first</p></div></div><div class="list">${cc.queue.filter(c=>c.status!=='Done').slice(0,4).map(callRow).join('')||'<div class="empty">Queue is clear</div>'}</div></section><div class="side">${ccRoleNote()}${ccActivity()}</div></div>`}
function ccQueue(){return `${ccLead('Contact center','Call queue','Take the next caller, resolve, wrap up.')}<div class="panel"><div class="panel-head"><div><h2>Live queue</h2><p>Demo callers across the portfolio</p></div><span class="count">${cc.queue.filter(c=>c.status!=='Done').length} active</span></div><div class="list">${cc.queue.filter(c=>c.status!=='Done').map(callRow).join('')||'<div class="empty">Queue is clear</div>'}</div></div>`}
function ccReservations(){const rows=cc.reservations.filter(r=>`${r.name} ${r.id} ${r.hotel}`.toLowerCase().includes(ccSearch.toLowerCase()));return `${ccLead('Reservations','Find a reservation','Any guest, any hotel. Confirm, hold or release from here.')}<div class="panel"><div class="toolbar"><strong class="table-title">All hotels</strong><input class="search" type="search" id="cc-search" placeholder="Guest, reservation or hotel" value="${esc(ccSearch)}" aria-label="Search reservations"></div><div class="list" id="cc-list">${rows.map(r=>`<div class="row static"><span class="row-icon">${esc(r.name.split(' ').map(x=>x[0]).join(''))}</span><span class="row-main"><strong>${esc(r.name)}</strong><small>${esc(r.id)} · ${esc(r.hotel)} · ${esc(r.dates)} · ${esc(r.type)}</small></span><span class="row-end"><span class="status ${mark(r.status)}">${esc(r.status)}</span></span>${r.status==='Hold'?`<button class="btn subtle" type="button" data-confirm="${esc(r.id)}">Confirm</button>`:''}</div>`).join('')||'<div class="empty">No reservations match</div>'}</div></div>`}
function ccCallbacks(){return `${ccLead('Promises to guests','Callbacks','Close each callback once the guest has been called.')}<div class="panel"><div class="panel-head"><div><h2>Callback list</h2><p>Visible to the current demo shift</p></div><span class="count">${cc.callbacks.filter(t=>t.status==='Open').length} open</span></div><div class="list">${cc.callbacks.map(t=>`<div class="row static"><span class="row-icon">${esc(t.name.split(' ').map(x=>x[0]).join(''))}</span><span class="row-main"><strong>${esc(t.name)}</strong><small>${esc(t.hotel)} · ${esc(t.note)}</small></span><span class="row-end"><span class="status ${mark(t.status)}">${esc(t.status)}</span></span>${t.status==='Open'?`<button class="btn subtle" type="button" data-callback="${t.id}">Called</button>`:''}</div>`).join('')}</div></div>`}
function ccBody(){return ccView==='queue'?ccQueue():ccView==='reservations'?ccReservations():ccView==='callbacks'?ccCallbacks():ccOverview()}
app.addEventListener('click',event=>{if(workspace!=='contactcenter')return;const b=event.target.closest('button');if(!b)return;
 if(b.dataset.ccview){ccView=b.dataset.ccview;render();return}
 if(b.dataset.take){const c=cc.queue.find(x=>x.id===b.dataset.take);if(c){c.status='On call';c.wait='On call';ccRecord('Call taken',`${c.caller} · ${c.hotel}`);render()}return}
 if(b.dataset.wrap){const c=cc.queue.find(x=>x.id===b.dataset.wrap);if(c){c.status='Done';ccRecord('Call wrapped up',`${c.caller} · ${c.reason}`);render();notify('Call closed in demo')}return}
 if(b.dataset.confirm){const r=cc.reservations.find(x=>x.id===b.dataset.confirm);if(r){r.status='Confirmed';ccRecord('Reservation confirmed',`${r.id} · ${r.hotel}`);render();notify('Reservation confirmed in demo')}return}
 if(b.dataset.callback){const t=cc.callbacks.find(x=>x.id===Number(b.dataset.callback));if(t){t.status='Done';ccRecord('Callback completed',`${t.name} · ${t.hotel}`);render();notify('Callback closed')}return}
 if(b.dataset.action==='sign-out'){window.dispatchEvent(new CustomEvent('desk-signout'))}
},true);
app.addEventListener('input',event=>{if(workspace==='contactcenter'&&event.target.id==='cc-search'){const caret=event.target.selectionStart;ccSearch=event.target.value;const list=document.querySelector('#cc-list');if(list){render();const el=document.querySelector('#cc-search');if(el){el.focus();el.setSelectionRange(caret,caret)}}}},true);
const currentProperty=()=>propertyDemo?properties[selectedProperty]:{name:'Ballard Locks House',place:'Seattle, WA'};
const mark=(status)=>status.toLowerCase().replace(/\s+/g,'-');
const now=()=>new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit'}).format(new Date());
const operatorImage=()=>operator==='Sam Okoro'?'<img src="./assets/personas/sam-okoro.webp" alt="">':operator==='Jordan Vale'?'<img src="./assets/personas/jordan-vale.webp" alt="">':operator==='Nadia Haddad'?'<img src="./assets/personas/nadia-haddad.webp" alt="">':operator==='Sofia Alvarez'?'<img src="./assets/personas/sofia-alvarez.webp" alt="">':'<span class="operator-initials" aria-hidden="true">AL</span>';
function record(title,detail){data.activity.unshift({title,detail:`${now()} · ${detail}`});data.activity=data.activity.slice(0,8)}
function notify(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3600)}
const count=status=>data.guests.filter(x=>x.status===status).length;
const roomCount=status=>data.rooms.filter(x=>x.status===status).length;
function header(){const property=currentProperty();return `<aside class="rail"><div class="rail-brand"><img src="./assets/harborline-mark.svg" alt=""><div><strong>Harborline</strong><small>${wsTitle}</small></div></div><div><span class="rail-group-label">WORKSPACE</span><nav class="rail-nav" aria-label="Front desk navigation">${[['overview','Overview'],['arrivals','Arrivals & guests'],['rooms','Room board'],['service','Guest service']].map(([key,label])=>`<button type="button" data-view="${key}" aria-label="${label}" ${view===key?'aria-current="page"':''}>${ico(key)}<span>${label}</span></button>`).join('')}</nav></div><div class="rail-bottom"><strong>${esc(property.name)}</strong>${esc(property.place)}<br>Shared front desk · demo environment<br>Role in token: ${esc(roleLabel)}</div></aside><div class="desk-main"><header class="topline"><div class="property"><i class="property-mark" aria-hidden="true"></i><strong>${esc(property.name)}</strong><span>· ${esc(property.place)}</span></div><div class="top-actions"><span class="demo-pill">${propertyDemo?'SCRIPTED ACCESS PREVIEW':'DEMO DATA'} · NOT CONNECTED TO PMS</span>${entraIdentity?'<span class="identity-pill">ENTRA SESSION</span><button class="top-signout" type="button" data-action="sign-out">Sign out</button>':'<a class="top-signin" href="https://kind-beach-0ba2dc30f.6.azurestaticapps.net/desk-auth.html" target="_blank" rel="noopener noreferrer">Sign in with Entra ↗</a>'}<div class="operator">${operatorImage()}<span><strong>${esc(operator)}</strong><small>${entraIdentity?esc(entraIdentity.username):'Front desk shift'}</small></span></div></div></header><main class="main-inner" id="desk-main">`}
function propertyJourney(){if(!propertyDemo)return '';const allowed=allowedProperty();return `<section class="property-journey" aria-label="Property access demonstration"><div class="property-journey-copy"><span class="eyebrow">${persona==='jordan'?'JORDAN · PROPERTY TRANSFER':'SAM · FRANCHISE DESK'}</span><h2>${persona==='jordan'?'One person. Different property access.':'Franchise context at the desk.'}</h2><p>${persona==='jordan'?'Choose a transfer stage, then open each property to see where Jordan can work.':'The franchise owns Sam’s sign-in; this screen previews the property scope after it.'}</p></div>${persona==='jordan'?`<div class="phase-steps" role="group" aria-label="Transfer stage">${[['franchise','1 · Franchise'],['managed','2 · Managed'],['return','3 · Return']].map(([value,label])=>`<button type="button" data-phase="${value}" aria-pressed="${phase===value}">${label}</button>`).join('')}</div>`:''}<div class="property-choices" role="group" aria-label="Choose property">${Object.entries(properties).map(([key,item])=>`<button type="button" data-property="${key}" aria-pressed="${selectedProperty===key}"><strong>${esc(item.name)}</strong><small>${key===allowed?'Access available':'Access denied'} · ${esc(item.place)}</small></button>`).join('')}</div><p class="property-proof">${persona==='jordan'?'Scripted preview of app authorization. Compare it with actual Entra assignments and a fresh sign-in before calling a tenant change proven.':'Scripted franchise property scope. Prove federation and device policy in the protected kiosk session.'}</p></section>`}
function denied(){const property=currentProperty(),granted=properties[allowedProperty()];return `<section class="access-denied" role="status"><span class="deny-symbol" aria-hidden="true">×</span><div class="eyebrow">ACCESS DENIED · SCRIPTED PREVIEW</div><h1>${esc(operator)} cannot open ${esc(property.name)}.</h1><p>This transfer stage grants ${esc(granted.name)}. The other property's guest roster, rooms and service queue stay unavailable.</p><div class="denied-actions"><button class="btn primary" type="button" data-property="${allowedProperty()}">Open ${esc(granted.name)} →</button><span>No tenant entitlement was changed by this preview.</span></div></section>`}
function lead(kicker,title,description,action=''){return `<div class="page-lead"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="lead-actions">${action}<button class="btn subtle" type="button" data-action="handover">End shift</button></div></div>`}
function stat(label,value,note,hot=false){return `<div class="stat ${hot?'hot':''}"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`}
function guestRow(g){return `<button type="button" class="row" data-guest="${esc(g.id)}"><span class="row-icon">${esc(g.initials)}</span><span class="row-main"><strong>${esc(g.name)}</strong><small>${esc(g.id)} · ${esc(g.type)} · ${g.nights} ${g.nights===1?'night':'nights'}</small></span><span class="row-end"><span class="status ${mark(g.status)}">${esc(g.status)}</span><small>${g.room?'Room '+esc(g.room):esc(g.time)}</small></span></button>`}
function activity(){return `<section class="panel"><div class="panel-head"><div><h2>Shift activity</h2><p>Actions in this demo session</p></div></div><div class="side-panel-body activity">${data.activity.map(a=>`<div class="activity-item"><i aria-hidden="true"></i><div><strong>${esc(a.title)}</strong><small>${esc(a.detail)}</small></div></div>`).join('')}</div></section>`}
function overview(){const arrivals=data.guests.filter(x=>x.status==='Arriving');return `${lead('Tonight at the desk','Good evening, '+operator.split(' ')[0]+'.','Keep arrivals moving, confirm room readiness and leave a clean handover.',`<button class="btn primary" type="button" data-view="arrivals">Work arrivals →</button>`)}<div class="stats">${stat('Arriving today',count('Arriving'),'Expected check-ins',true)}${stat('Ready rooms',roomCount('Ready'),'Available for assignment')}${stat('In house',count('In house'),'Current guest stays')}${stat('Open requests',data.tasks.filter(x=>x.status==='Open').length,'For the next handover')}</div><div class="work-grid"><section class="panel"><div class="panel-head"><div><h2>Upcoming arrivals</h2><p>Confirm identity and assign a ready room</p></div><span class="count">${arrivals.length} waiting</span></div><div class="list">${arrivals.length?arrivals.map(guestRow).join(''):'<div class="empty">All sample arrivals are checked in.</div>'}</div></section><div class="side-stack"><section class="panel"><div class="panel-head"><h2>On this shift</h2></div><div class="side-panel-body"><div class="shift-card"><div class="shift-person">${operatorImage()}<div><strong>${esc(operator)}</strong><small>Shared desk · demo shift</small></div></div><p>This is a simulated app session. Use End shift to clear this screen before the next person uses the shared kiosk.</p></div></div></section>${activity()}</div></div>`}
function arrivals(){const guests=data.guests.filter(g=>g.status!=='Departed'&&`${g.name} ${g.id} ${g.room||''}`.toLowerCase().includes(search.toLowerCase()));return `${lead('Guest operations','Arrivals & guests','Open a reservation to check in, check out or review its room.') }<div class="panel"><div class="toolbar"><strong class="table-title">Guest roster</strong><input class="search" type="search" id="guest-search" aria-label="Search guests" placeholder="Search name, booking or room" value="${esc(search)}"></div><div class="list">${guests.length?guests.map(guestRow).join(''):'<div class="empty">No matching sample guests.</div>'}</div></div>`}
function rooms(){return `${lead('Property operations','Room board','Room readiness controls which arrivals can be checked in.') }<div class="panel"><div class="panel-head"><div><h2>Rooms in this demo</h2><p>Select a room to update housekeeping readiness</p></div><span class="count">${data.rooms.length} rooms</span></div><div class="room-grid">${data.rooms.map(r=>`<button class="room ${mark(r.status)}" type="button" data-room="${r.number}"><strong>${r.number}</strong><span>${esc(r.type)} · ${esc(r.floor)}</span><span class="status ${mark(r.status)}">${esc(r.status)}</span></button>`).join('')}</div></div>`}
function service(){return `${lead('Guest operations','Guest service','Create a request and close it when the team completes the work.',`<button class="btn primary" type="button" data-action="new-task">New request +</button>`)}<div class="panel"><div class="panel-head"><div><h2>Service queue</h2><p>Visible to the current demo shift</p></div><span class="count">${data.tasks.filter(t=>t.status==='Open').length} open</span></div>${data.tasks.length?data.tasks.map(t=>`<div class="task-row"><div><strong>${esc(t.category)} · Room ${esc(t.room)}</strong><p>${esc(t.note)}</p><small>${esc(t.owner)} · ${esc(t.status)}</small></div><div class="task-actions"><span class="status ${mark(t.status)}">${esc(t.status)}</span>${t.status==='Open'?`<button class="btn small" type="button" data-complete="${t.id}">Mark done</button>`:''}</div></div>`).join(''):'<div class="empty">No service requests in this demo shift.</div>'}</div>`}
function detail(){if(!drawer)return '';if(drawer.kind==='guest'){const g=data.guests.find(x=>x.id===drawer.id);if(!g)return '';const ready=data.rooms.filter(r=>r.type===g.type&&r.status==='Ready');return `<div class="sheet-backdrop" data-action="close-sheet"><aside class="sheet" role="dialog" aria-modal="true" aria-label="Guest details"><div class="sheet-head"><div><div class="eyebrow">Reservation ${esc(g.id)}</div><h2>${esc(g.name)}</h2><p>${esc(g.status)} · ${esc(g.party)} ${g.party===1?'guest':'guests'} · ${esc(g.type)}</p></div><button class="icon-btn" type="button" data-action="close-sheet" aria-label="Close details">×</button></div><dl class="details"><div><dt>Stay</dt><dd>${g.nights} ${g.nights===1?'night':'nights'}</dd></div><div><dt>Room</dt><dd>${g.room?esc(g.room):'Unassigned'}</dd></div><div><dt>Arrival</dt><dd>${esc(g.time)}</dd></div><div><dt>Status</dt><dd>${esc(g.status)}</dd></div></dl><div class="notice">Sample reservation. No real guest record or hotel system is connected.</div>${g.note?`<p class="note-inline"><strong>Desk note:</strong> ${esc(g.note)}</p>`:''}${g.status==='Arriving'?`<label class="field" for="assign-room">Assign a ready ${esc(g.type)} room<select id="assign-room"><option value="">Choose a room</option>${ready.map(r=>`<option value="${r.number}">${r.number} · ${esc(r.floor)}</option>`).join('')}</select></label>${ready.length?'':'<div class="alert">No matching room is ready. Update the room board after housekeeping confirms readiness.</div>'}<div class="sheet-actions"><button class="btn primary" type="button" data-action="checkin" ${ready.length?'':'disabled'}>Confirm check-in</button><button class="btn" type="button" data-view="rooms">Room board</button></div>`:`<div class="sheet-actions"><button class="btn danger" type="button" data-action="checkout">Check out guest</button><button class="btn" type="button" data-action="new-task" data-prefill-room="${esc(g.room)}">Service request</button></div>`}</aside></div>`}
 if(drawer.kind==='room'){const r=data.rooms.find(x=>x.number===drawer.id),g=data.guests.find(x=>x.room===r.number&&x.status==='In house');return `<div class="sheet-backdrop" data-action="close-sheet"><aside class="sheet" role="dialog" aria-modal="true" aria-label="Room details"><div class="sheet-head"><div><div class="eyebrow">${esc(r.floor)} · ${esc(r.type)}</div><h2>Room ${esc(r.number)}</h2><p><span class="status ${mark(r.status)}">${esc(r.status)}</span></p></div><button class="icon-btn" type="button" data-action="close-sheet" aria-label="Close details">×</button></div><div class="notice">Readiness is simulated here. Confirm housekeeping and guest status in the real property system before assigning a room.</div>${g?`<p class="note-inline">Currently assigned to ${esc(g.name)}.</p>`:''}<div class="sheet-actions">${r.status==='Cleaning'?`<button class="btn primary" type="button" data-action="ready-room">Mark ready</button>`:r.status==='Ready'?`<button class="btn" type="button" data-action="clean-room">Send to cleaning</button>`:'<button class="btn" type="button" disabled>Occupied</button>'}</div></aside></div>`}
 return `<div class="sheet-backdrop" data-action="close-sheet"><aside class="sheet" role="dialog" aria-modal="true" aria-label="New service request"><div class="sheet-head"><div><div class="eyebrow">Guest service</div><h2>New request</h2><p>Send a task to the property team.</p></div><button class="icon-btn" type="button" data-action="close-sheet" aria-label="Close details">×</button></div><form id="task-form"><label class="field">Room number<input name="room" inputmode="numeric" maxlength="4" required value="${esc(drawer.room||'')}" placeholder="e.g. 608"></label><label class="field">Team<select name="category"><option>Housekeeping</option><option>Maintenance</option><option>Guest services</option></select></label><label class="field">What needs attention?<textarea name="note" maxlength="240" required placeholder="Describe the request"></textarea></label><button class="btn primary full" type="submit">Add to service queue</button></form></aside></div>`}
function lockScreen(){return `<div class="lock"><div class="lock-card"><img src="./assets/harborline-mark.svg" alt="Harborline"><div class="eyebrow">Shared front desk · demo</div><h1>Shift ended. Desk cleared.</h1><p>The previous demo operator’s guest screen and work state have been removed.</p>${entraIdentity?`<p>Signed in as <strong>${esc(operator)}</strong>. Sign out before the next person uses this browser.</p><button type="button" class="btn primary" data-action="sign-out">Sign out of Entra</button>`:`<label class="field" for="next-operator">Next operator<select id="next-operator"><option value="Avery Lee">Avery Lee · front desk</option><option value="Sam Okoro">Sam Okoro · night audit</option></select></label><button type="button" class="btn primary" data-action="new-shift">Start fresh demo shift</button>`}<div class="fineprint">Sample guest work is local to this page. End shift does not prove Windows kiosk cleanup or invalidate another application session.</div></div></div>`}
function render(){if(workspace==='contactcenter'){app.innerHTML=`<div class="desk-shell">${ccHeader()}${ccBody()}</main></div></div>`;return}app.innerHTML=locked?lockScreen():`<div class="desk-shell">${header()}${propertyJourney()}${propertyAllowed()?(view==='overview'?overview():view==='arrivals'?arrivals():view==='rooms'?rooms():service()):denied()}</main></div></div>${propertyAllowed()?detail():''}`}
app.addEventListener('click',event=>{
 if(workspace==='contactcenter')return;
 const button=event.target.closest('button');if(!button)return;
 if(button.dataset.phase){phase=button.dataset.phase;selectedProperty=allowedProperty();drawer=null;view='overview';data=seed();record('Property context changed',`${operator} · ${currentProperty().name} · scripted preview`);render();return}
 if(button.dataset.property){selectedProperty=button.dataset.property;drawer=null;view='overview';render();return}
 if(!propertyAllowed()&&!['sign-out','handover'].includes(button.dataset.action)){notify('Access denied for this property in the scripted preview');return}
 if(button.dataset.view){view=button.dataset.view;drawer=null;search='';render();return}
 if(button.dataset.guest){drawer={kind:'guest',id:button.dataset.guest};render();return}
 if(button.dataset.room){drawer={kind:'room',id:button.dataset.room};render();return}
 if(button.dataset.complete){const task=data.tasks.find(x=>x.id===Number(button.dataset.complete));if(task){task.status='Done';record('Request completed',`${task.category} · Room ${task.room}`);render();notify('Request marked done')}return}
 const action=button.dataset.action;
 if(action==='sign-out'){window.dispatchEvent(new CustomEvent('desk-signout'));return}
 if(action==='close-sheet'){drawer=null;render();return}
 if(action==='new-task'){drawer={kind:'task',room:button.dataset.prefillRoom||''};render();return}
 if(action==='checkin'){
  const roomNumber=document.querySelector('#assign-room')?.value,g=data.guests.find(x=>x.id===drawer?.id),room=data.rooms.find(x=>x.number===roomNumber);
  if(!g||g.status!=='Arriving'||!room||room.status!=='Ready'||room.type!==g.type){notify('Select a matching ready room');return}
  g.status='In house';g.room=room.number;room.status='Occupied';record(`${g.name} checked in`,`Room ${room.number} assigned`);drawer=null;render();notify(`Check-in recorded in demo · Room ${room.number}`);return
 }
 if(action==='checkout'){const g=data.guests.find(x=>x.id===drawer?.id);if(!g||g.status!=='In house')return;const room=data.rooms.find(x=>x.number===g.room);if(room)room.status='Cleaning';record(`${g.name} checked out`,`Room ${g.room} sent to cleaning`);g.status='Departed';g.room=null;drawer=null;render();notify('Demo checkout complete');return}
 if(action==='ready-room'||action==='clean-room'){const room=data.rooms.find(x=>x.number===drawer?.id);if(!room||room.status==='Occupied')return;room.status=action==='ready-room'?'Ready':'Cleaning';record(`Room ${room.number} ${room.status.toLowerCase()}`,'Housekeeping status updated in demo');drawer=null;render();notify(`Room ${room.number} marked ${room.status.toLowerCase()}`);return}
 if(action==='handover'){locked=true;data=seed();drawer=null;search='';render();return}
 if(action==='new-shift'){operator=document.querySelector('#next-operator')?.value||'Sam Okoro';locked=false;data=seed();view='overview';record('Fresh shift started',`${operator} · sample records reset`);render();notify('Fresh demo shift ready')}
});
app.addEventListener('input',event=>{if(event.target.id==='guest-search'){const caret=event.target.selectionStart;search=event.target.value;const list=document.querySelector('.list');const guests=data.guests.filter(g=>g.status!=='Departed'&&`${g.name} ${g.id} ${g.room||''}`.toLowerCase().includes(search.toLowerCase()));list.innerHTML=guests.length?guests.map(guestRow).join(''):'<div class="empty">No matching sample guests.</div>';event.target.setSelectionRange(caret,caret)}});
app.addEventListener('submit',event=>{if(event.target.id!=='task-form')return;event.preventDefault();const values=new FormData(event.target),room=String(values.get('room')||'').trim(),category=String(values.get('category')||''),note=String(values.get('note')||'').trim();if(!/^\d{3,4}$/.test(room)){notify('Enter a three- or four-digit room number');return}if(!note){notify('Describe the request');return}data.tasks.unshift({id:Date.now(),room,category,note,status:'Open',owner:category==='Housekeeping'?'Rooms team':category==='Maintenance'?'Engineering':'Front desk'});record('Service request added',`${category} · Room ${room}`);drawer=null;view='service';render();notify('Request added to demo queue')});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&drawer){drawer=null;render()}});
render();
